/**
 * football/src/utils/playerCulture.ts — World Cup '22 player culture database.
 *
 * Mirrors basketball/src/utils/playerCulture.ts and baseball/src/utils/playerCulture.ts
 * structurally so the shared commentary engine (`shared/commentary/selectCommentary.ts`)
 * can dispatch through the same code path.
 *
 * KEYING: Lowercase cultural surname. The lookup function tries last word,
 * second-to-last word, and first word of the FIFA full name in players.json,
 * which means:
 *   - "Lionel Andrés Messi Cuccittini" → key "messi"  (2nd-to-last hit)
 *   - "Kylian Mbappé Lottin"           → key "mbappé" (2nd-to-last hit)
 *   - "Neymar da Silva Santos Junior"  → key "neymar" (first-word hit, after Junior strip)
 *   - "Jude Bellingham"                → key "bellingham" (last-word hit)
 *
 * VOICE: Modeled on the great soccer announcers — Peter Drury (poetic,
 * theatrical, "this is what you came for!"), Ray Hudson (extravagant,
 * "magisterial!", baroque metaphors), Martin Tyler (iconic call moments),
 * and Ian Darke / Jim Beglin (measured analysis). Mix freely depending on
 * the moment: tier1/bigGame leans Drury/Hudson; defensive/quietGame leans
 * Tyler/Beglin; controversy stays earthbound and dry.
 */

export interface FootballPlayerCulture {
  /** Common-usage nicknames. First entry is preferred for templated framing. */
  nicknames: string[];
  /** One-line summary of who this player is to global football fans. */
  knownFor: string;
  /** Coarse pricing tier: helps generic templates calibrate framing. */
  salaryTier: "max" | "star" | "role" | "value" | "flier";
  // ── Story tiers (descending celebration) ─────────────────────────────────
  /** Top-tier identity statements — "best of his generation" register. */
  tier1: string[];
  /** Career arc / origin story beats. */
  tier2: string[];
  /** Background trivia / specific lore. */
  tier3: string[];
  // ── Performance buckets (used by cultureFraming) ─────────────────────────
  /** Lines for over-performance vs projection (high starRatio + win). */
  overperform: string[];
  /** Lines for under-performance / bust hands. */
  underperform: string[];
  /** Lines for normal "as expected" performance. */
  onPace: string[];
  // ── Flavor pools ─────────────────────────────────────────────────────────
  /** Loose play / careless possession / bookings — soccer analogue of
   *  basketball's "turnovers" bucket. */
  loosePlay: string[];
  /** Defensive contribution / tackles / pressing / positional discipline. */
  defensive: string[];
  /** Lines for elite outlier games (hat-tricks, MOTM-level performances). */
  bigGame: string[];
  /** Lines for muted appearances / sub cameos / substitution. */
  quietGame: string[];
  /** Lines about off-pitch / federation / racism / VAR / trade drama. */
  controversy: string[];
  /** Hint at a specific real game worth looking up — gives users a clue. */
  famousGameHint: string[];
  /** Per-opponent flavor, keyed by 3-letter nation code (uppercase). */
  opponentFlavor?: Record<string, string>;
  /** Career arc anchor — club affiliation, transfer story. */
  formerTeam?: string[];
  /** International rivalries (Argentina-Brazil, Spain-Portugal, etc.). */
  rivalry?: string[];
  /** Career milestones — WC titles, Ballon d'Or, Golden Boot, etc. */
  milestones?: string[];
  /** Hot-streak / cold-streak narrative lines. */
  streakLines?: string[];
  /** Pre-resolved attributions for specific real games — exact match by date+opponent. */
  signatureGames?: { date: string; opponent: string; fp: number; line: string }[];
  /** Lines anchored on the player's price tag / value-for-money debate. */
  salaryNarrative?: string[];
  /** Lines about the player's national team context / squad role. */
  teamContext?: string[];
  /** Path to the top — youth academy, club transfer history, breakthrough moment. */
  draftAndPath?: string[];
}

